create table xxventuri.xxeba_sales_crm_appointments (
    appt_id             number not null enable,
    row_version_number  number,
    customer_id         number,
    contact_person_id   number,
    contact_location_id number,
    appointment_type    varchar2(100 byte),
    appointment_date    timestamp(6),
    appointment_purpose varchar2(100 byte),
    comments            varchar2(100 byte),
    appointment_status  varchar2(20 byte),
    status_comments     varchar2(50 byte),
    salesrep_id         number,
    appointment_source  varchar2(1 byte),
    visited_on          date,
    limit_existed       varchar2(1 byte),
    created             timestamp(6) with local time zone,
    created_by          varchar2(50 byte),
    updated             timestamp(6) with local time zone,
    updated_by          varchar2(50 byte),
    created_temp        varchar2(100 byte),
    updated_temp        varchar2(100 byte),
    latitude            varchar2(50 byte),
    longitude           varchar2(50 byte),
    source_application  char(1 byte),
    negotiation_id      number
);


